// @vitest-environment node
// Frontend schemas vs the backend's OpenAPI document (AGENTS §21).
// `openapi.json` is generated by the backend; its own test fails when the
// snapshot is stale (backend/tests/test_openapi_contract.py), so together
// the two tests catch drift on either side.
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import { z } from 'zod'
import * as auth from './auth'
import * as credentials from './credentials'
import * as executions from './executions'
import * as nodes from './nodes'
import * as plugins from './plugins'
import * as projects from './projects'
import * as reports from './reports'
import * as system from './system'
import {
    ApiClient,
    DEFAULT_BASE_URL,
    type HttpMethod,
    type RequestOptions,
} from './client'
import { errorEnvelopeSchema } from './errors'

// -- the OpenAPI document ----------------------------------------------------

interface JsonSchema {
    $ref?: string | undefined
    anyOf?: JsonSchema[] | undefined
    oneOf?: JsonSchema[] | undefined
    type?: string | string[] | undefined
    enum?: unknown[] | undefined
    const?: unknown
    format?: string | undefined
    properties?: Record<string, JsonSchema> | undefined
    required?: string[] | undefined
    items?: JsonSchema | undefined
}
const jsonSchema: z.ZodType<JsonSchema> = z.lazy(() =>
    z.object({
        $ref: z.string().optional(),
        anyOf: z.array(jsonSchema).optional(),
        oneOf: z.array(jsonSchema).optional(),
        type: z.union([z.string(), z.array(z.string())]).optional(),
        enum: z.array(z.unknown()).optional(),
        const: z.unknown().optional(),
        format: z.string().optional(),
        properties: z.record(z.string(), jsonSchema).optional(),
        required: z.array(z.string()).optional(),
        items: jsonSchema.optional(),
    }),
)
const jsonBody = z.object({
    content: z
        .object({
            'application/json': z.object({ schema: jsonSchema }).optional(),
        })
        .optional(),
})
const documentSchema = z.object({
    paths: z.record(
        z.string(),
        z.record(
            z.string(),
            z.object({
                requestBody: jsonBody.optional(),
                responses: z.record(z.string(), jsonBody),
            }),
        ),
    ),
    components: z.object({ schemas: z.record(z.string(), jsonSchema) }),
})
const document = documentSchema.parse(
    JSON.parse(
        readFileSync(new URL('./openapi.json', import.meta.url), 'utf8'),
    ),
)

// -- normalization: both sides reduced to what the wire format promises ------

interface Shape {
    type: string // 'object', 'array', 'union', 'string:date-time', 'enum(a,b)', ...
    props?: Record<string, { required: boolean; shape: Shape }>
    items?: Shape
    members?: Shape[]
}

function resolve(ref: string): JsonSchema {
    const name = ref.replace('#/components/schemas/', '')
    const target = document.components.schemas[name]
    if (!target) throw new Error(`unresolvable $ref ${ref}`)
    return target
}

function normalize(schema: JsonSchema): Shape {
    if (schema.$ref) return normalize(resolve(schema.$ref))
    // Pydantic writes nullables as anyOf, Zod as a type array: same union.
    const variants =
        schema.anyOf ??
        schema.oneOf ??
        (Array.isArray(schema.type)
            ? schema.type.map((type) => ({ ...schema, type }))
            : undefined)
    if (variants) {
        const members = variants.map(normalize).flatMap((s) => s.members ?? [s])
        // ponytail: members are matched by sort order, so two object members
        // differing only in optionality may pair up wrongly; fine until unions of objects appear.
        members.sort((a, b) =>
            JSON.stringify(a).localeCompare(JSON.stringify(b)),
        )
        return members.length === 1 && members[0]
            ? members[0]
            : { type: 'union', members }
    }
    if (schema.enum)
        return { type: `enum(${schema.enum.map(String).sort().join(',')})` }
    if ('const' in schema) return { type: `enum(${String(schema.const)})` }
    if (schema.type === 'object' && schema.properties) {
        const required = new Set(schema.required ?? [])
        const props: NonNullable<Shape['props']> = {}
        for (const [name, prop] of Object.entries(schema.properties)) {
            props[name] = {
                required: required.has(name),
                shape: normalize(prop),
            }
        }
        return { type: 'object', props }
    }
    if (schema.type === 'object') return { type: 'record' }
    if (schema.type === 'array')
        return { type: 'array', items: normalize(schema.items ?? {}) }
    // Type arrays were turned into unions above; no type means any value.
    if (typeof schema.type !== 'string') return { type: 'unknown' }
    return {
        type: schema.format ? `${schema.type}:${schema.format}` : schema.type,
    }
}

function fromZod(schema: z.ZodType): Shape {
    // 'input': what the frontend schema accepts, which is what must cover the wire.
    return normalize(jsonSchema.parse(z.toJSONSchema(schema, { io: 'input' })))
}

/**
 * Differences that would make valid backend responses fail (or pass
 * unchecked) in the frontend. Exact field sets: a new backend field must be
 * a deliberate frontend change, not silently ignored.
 */
function compare(front: Shape, back: Shape, at = '$'): string[] {
    if (front.type !== back.type)
        return [`${at}: frontend ${front.type}, backend ${back.type}`]
    const issues: string[] = []
    if (front.items && back.items)
        issues.push(...compare(front.items, back.items, `${at}[]`))
    if (front.members && back.members) {
        if (front.members.length !== back.members.length)
            issues.push(`${at}: union members differ`)
        front.members.forEach((m, i) => {
            const other = back.members?.[i]
            if (other) issues.push(...compare(m, other, `${at}|${String(i)}`))
        })
    }
    const names = new Set([
        ...Object.keys(front.props ?? {}),
        ...Object.keys(back.props ?? {}),
    ])
    for (const name of [...names].sort()) {
        const f = front.props?.[name]
        const b = back.props?.[name]
        const path = `${at}.${name}`
        if (!f) issues.push(`${path}: missing in frontend schema`)
        else if (!b) issues.push(`${path}: not in backend contract`)
        else {
            if (f.required && !b.required)
                issues.push(
                    `${path}: required in frontend, optional in backend`,
                )
            issues.push(...compare(f.shape, b.shape, path))
        }
    }
    return issues
}

// -- what the services actually send -----------------------------------------

interface Call {
    method: HttpMethod
    path: string
    schema: z.ZodType
    body: unknown
}

/** Records each request instead of sending it. */
class RecordingClient extends ApiClient {
    readonly calls: Call[] = []
    override request<S extends z.ZodType>(
        method: HttpMethod,
        path: string,
        schema: S,
        options: RequestOptions = {},
    ): Promise<z.output<S>> {
        this.calls.push({ method, path, schema, body: options.body })
        return new Promise<never>(() => undefined)
    }
}

const recorder = new RecordingClient()
// Every service function, called once. Add new services here; the coverage
// test below fails if one is missing.
void auth.login(recorder, { username: 'u', password: 'p' })
void auth.logout(recorder)
void auth.fetchCurrentUser(recorder)
const draft = projects.projectDraftSchema.parse({})
void projects.listProjects(recorder, {
    offset: 0,
    limit: 10,
    q: 'a',
    status: ['draft'],
    sort: '-name',
})
void projects.getProject(recorder, 'p')
void projects.createProject(recorder, { name: 'n', description: 'd' })
void projects.updateProject(recorder, 'p', {
    name: 'n',
    description: 'd',
    draft,
    expected_revision: 1,
})
void projects.duplicateProject(recorder, 'p', 'copy')
void projects.deleteProject(recorder, 'p')
void projects.validateProject(recorder, 'p')
void projects.publishProject(recorder, 'p', 1)
void projects.listProjectVersions(recorder, 'p')
void projects.getProjectVersion(recorder, 'p', 1)
void executions.listExecutions(recorder, { status: ['failed'], limit: 5 })
void executions.getExecutionStatusCounts(recorder)
void executions.listProjectExecutions(recorder, 'p')
void executions.getExecution(recorder, 'e')
void executions.listExecutionEvents(recorder, 'e', { after: 3 })
void executions.cancelExecution(recorder, 'e', 'r')
void executions.executeProjectVersion(recorder, 'p', 1, { k: 'v' })
void executions.invokeTrigger(recorder, 'p', 't', { k: 'v' })
void reports.getExecutionReport(recorder, 'e')
void nodes.listNodeDefinitions(recorder)
void nodes.validateNodeConfig(recorder, 'core.http', { url: 'https://x' })
void credentials.listCredentials(recorder)
void credentials.getCredential(recorder, 'c')
void credentials.createCredential(recorder, {
    name: 'c',
    kind: 'api_key',
    description: 'd',
    value: 'v',
})
void credentials.updateCredential(recorder, 'c', { description: 'd' })
void credentials.deleteCredential(recorder, 'c')
void plugins.listPlugins(recorder)
void system.getSystemStatus(recorder)
const modules: Record<string, unknown>[] = [
    auth,
    projects,
    executions,
    reports,
    nodes,
    credentials,
    plugins,
    system,
]
const serviceFunctions = modules.flatMap((module) =>
    Object.values(module).filter((v) => typeof v === 'function'),
)

function operation(method: HttpMethod, path: string) {
    const full = `${DEFAULT_BASE_URL}${path}`
    const exact = document.paths[full]
    const templated = Object.entries(document.paths).find(([template]) =>
        new RegExp(`^${template.replace(/\{[^}]+\}/g, '[^/]+')}$`).test(full),
    )?.[1]
    return (exact ?? templated)?.[method.toLowerCase()]
}

// -- tests ---------------------------------------------------------------------

describe('frontend schemas match the backend OpenAPI contract', () => {
    it('every service function is covered', () => {
        expect(recorder.calls).toHaveLength(serviceFunctions.length)
    })

    it.each(recorder.calls.map((c) => [`${c.method} ${c.path}`, c] as const))(
        '%s',
        (_name, call) => {
            const op = operation(call.method, call.path)
            if (!op)
                throw new Error(
                    `${call.method} ${DEFAULT_BASE_URL}${call.path} is not in the contract`,
                )

            const success = Object.keys(op.responses)
                .filter((status) => status.startsWith('2'))
                .sort()[0]
            expect(success, 'documented success response').toBeDefined()
            const responseSchema =
                op.responses[success ?? '']?.content?.['application/json']
                    ?.schema
            if (responseSchema) {
                expect(
                    compare(fromZod(call.schema), normalize(responseSchema)),
                ).toEqual([])
            } else {
                expect(
                    call.schema.safeParse(undefined).success,
                    'no-content response accepts an empty body',
                ).toBe(true)
            }

            const requestSchema =
                op.requestBody?.content?.['application/json']?.schema
            if (!requestSchema) {
                expect(call.body).toBeUndefined()
                return
            }
            const sent = Object.keys(
                z.record(z.string(), z.unknown()).parse(call.body),
            )
            // An optional body is `X | null`; compare against X.
            const request = normalize(requestSchema)
            const body =
                request.members?.find((m) => m.type !== 'null') ?? request
            // A free-form JSON object (execution input) accepts any field.
            if (body.type === 'record') return
            const props = body.props ?? {}
            expect(
                sent.filter((k) => !(k in props)),
                'fields the backend does not accept',
            ).toEqual([])
            expect(
                Object.keys(props).filter(
                    (k) => props[k]?.required && !sent.includes(k),
                ),
                'required fields not sent',
            ).toEqual([])
        },
    )

    it('the error envelope matches ErrorResponse', () => {
        expect(
            compare(
                fromZod(errorEnvelopeSchema),
                normalize({ $ref: '#/components/schemas/ErrorResponse' }),
            ),
        ).toEqual([])
    })
})

describe('the comparison itself', () => {
    const back = normalize({
        type: 'object',
        properties: {
            id: { type: 'string' },
            at: {
                anyOf: [
                    { type: 'string', format: 'date-time' },
                    { type: 'null' },
                ],
            },
            note: { type: 'string' },
        },
        required: ['id', 'at'],
    })
    const front = (shape: z.ZodRawShape) => fromZod(z.object(shape))

    it('accepts an equivalent schema', () => {
        expect(
            compare(
                front({
                    id: z.string(),
                    at: z.iso.datetime().nullable(),
                    note: z.string().optional(),
                }),
                back,
            ),
        ).toEqual([])
    })

    it('reports missing, extra, mistyped and too-strict fields', () => {
        expect(
            compare(
                front({
                    id: z.number(),
                    at: z.iso.datetime(),
                    note: z.string(),
                    extra: z.string(),
                }),
                back,
            ),
        ).toEqual([
            '$.at: frontend string:date-time, backend union',
            '$.extra: not in backend contract',
            '$.id: frontend number, backend string',
            '$.note: required in frontend, optional in backend',
        ])
        expect(
            compare(
                front({ id: z.string(), at: z.iso.datetime().nullable() }),
                back,
            ),
        ).toEqual(['$.note: missing in frontend schema'])
    })
})

describe('query parameter enums match the backend', () => {
    it('project list sort orders', () => {
        expect(projects.projectSortSchema.options).toEqual(
            document.components.schemas.ProjectSort?.enum,
        )
    })
})
